const a=e=>Number(e.params.n)*Number(e.params.s),n=e=>e.sol.ok?Math.max(0,...e.sol.members.filter(t=>t.id.startsWith("c")).map(t=>Math.max(Math.abs(t.maxM.value),Math.abs(t.minM.value)))):0,o=[{id:"l.rc-sys-joints.long",xp:30,title:{en:"Build a 70 m frame without joints and read the sway of its end columns",ar:"ابني إطار 70 م من غير فواصل واقرا حركة أعمدته الطرفية"},check:e=>e.template==="longframe"&&e.params.joints==="0"&&a(e)>=70&&Number(e.params.dT)>0&&e.tab==="hand"},{id:"l.rc-sys-joints.cut",xp:40,title:{en:"Cut the 70 m frame with joints so that no part is longer than 40 m",ar:"اقطع الإطار الـ 70 م بفواصل علشان مفيش جزء أطول من 40 م"},check:e=>e.template==="longframe"&&a(e)>=70&&e.params.joints!=="0"&&a(e)/(Number(e.params.joints)+1)<=40.000000001},{id:"l.rc-sys-joints.hinge",xp:30,title:{en:"Hinge the column bases: the same sway bends them only half as much",ar:"خلّي ركائز الأعمدة مفصلية: نفس الحركة بتحنيهم نص الكمية"},check:e=>e.template==="longframe"&&e.params.bases==="hinged"&&Number(e.params.dT)>0&&n(e)>0}],s=[{id:"l.rc-sys-joints.corbel",xp:20,title:{en:"Open the floating-bay detail and find t ≥ a and the outer depth ≥ d/2",ar:"افتح تفصيلة الباكية العائمة ولاقي t ≥ a والعمق عند الطرف ≥ d/2"},check:e=>e.tab==="details"&&e.detail==="corbel"},{id:"l.rc-sys-joints.roof",xp:20,title:{en:"Open the roof joint and the floor joint details",ar:"افتح تفصيلة فاصل السطح وتفصيلة فاصل الأرضية"},check:e=>e.tab==="details"&&e.detail==="floor"},{id:"l.rc-sys-joints.casting",xp:20,title:{en:"Open the casting-joint detail: where is the moment nearly zero?",ar:"افتح تفصيلة فاصل الصب: العزم تقريباً صفر فين؟"},check:e=>e.tab==="details"&&e.detail==="casting"}],i=[{id:"l.rc-sys-joints.cont",xp:30,title:{en:"Let the middle support of the continuous beam sink 40 mm: its support moment melts away",ar:"خلّي الركيزة الوسطية للكمرة المستمرة تهبط 40 مم: عزم الركيزة بيسيح"},check:e=>e.template==="settle"&&e.params.sys==="cont"&&Number(e.params.d)>=40&&e.sol.ok},{id:"l.rc-sys-joints.gerber",xp:40,title:{en:"Put the hinge at L/5 and settle it again: nothing changes",ar:"حط المفصلة عند L/5 ونزّلها تاني: ولا حاجة بتتغيّر"},check:e=>e.template==="settle"&&e.params.sys==="gerber"&&Number(e.params.d)>=40&&e.sol.ok}],r={sections:[{id:"why",title:{en:"Why large buildings are cut",ar:"ليه المباني الكبيرة بتتقطع"},blocks:[{t:"p",text:{en:"A concrete building is not free to change: its slabs expand in the sun and shrink as they dry, its footings settle unequally, and a stiff part next to a flexible one pulls on it. Where these movements would crack the building, it is cut by a **joint** into parts that can move on their own. There are four kinds:",ar:"المبنى الخرساني مش حر يتغيّر: بلاطاته بتتمدد في الشمس وبتنكمش وهي بتنشف، وقواعده بتهبط بشكل مش متساوي، والجزء الجاسئ جنب جزء مرن بيشده. وفي الأماكن اللي الحركات دي هتشرخ فيها المبنى، بيتقطع بـ**فاصل** لأجزاء كل واحد فيها يتحرك لوحده. وفيه أربع أنواع:"}},{t:"table",head:[{en:"Joint",ar:"الفاصل"},{en:"Cause",ar:"السبب"},{en:"Through the footings?",ar:"بيعدّي القواعد؟"}],rows:[[{en:"expansion joint",ar:"فاصل تمدد"},{en:"temperature (and shrinkage) of long buildings",ar:"الحرارة (والانكماش) في المباني الطويلة"},{en:"no — the footings hardly feel the temperature",ar:"لأ — القواعد تقريباً مابتحسش بالحرارة"}],[{en:"structural joint",ar:"فاصل إنشائي"},{en:"a change of system, of height or an irregular plan (L, T)",ar:"تغيير في النظام أو الارتفاع أو مسقط غير منتظم (L أو T)"},{en:"usually no",ar:"غالباً لأ"}],[{en:"settlement joint",ar:"فاصل هبوط"},{en:"unequal settlement: heavy next to light, weak soil",ar:"هبوط غير متساوي: تقيل جنب خفيف، وتربة ضعيفة"},{en:"yes — each part on its own footings",ar:"أيوه — كل جزء على قواعده"}],[{en:"casting (construction) joint",ar:"فاصل صب"},{en:"the concrete is cast in stages",ar:"الخرسانة بتتصب على مراحل"},{en:"—",ar:"—"}]]},{t:"quiz",q:{kind:"mcq",q:{en:"Which joint must continue through the foundations?",ar:"أنهي فاصل لازم يكمّل جوه الأساسات؟"},options:[{en:"the settlement joint",ar:"فاصل الهبوط"},{en:"the expansion joint",ar:"فاصل التمدد"},{en:"the casting joint",ar:"فاصل الصب"}],answer:0,explain:{en:"Its whole purpose is to let one part settle more than the other, so the footings must be separate too.",ar:"الهدف كله إن جزء يهبط أكتر من التاني، فالقواعد لازم تبقى منفصلة هي كمان."}}}]},{id:"expansion",title:{en:"Expansion joints: temperature and length",ar:"فواصل التمدد: الحرارة والطول"},blocks:[{t:"p",text:{en:"When the roof warms up by $\\Delta T$ it wants to grow by $\\alpha\\,\\Delta T$ per metre ($\\alpha = 10^{-5}$/°C). The columns hold it back, and the frame finds a middle point that does not move: every column head is pushed out by $\\alpha\\,\\Delta T\\,x$, where $x$ is its distance from that centre — $\\Delta$, $2\\Delta$, $3\\Delta$… outwards. The end columns are bent the most, and their moment grows with the length of the building. So long buildings are cut into parts of at most about **40 m** (40–45 m is quoted) by joints about **2 cm** wide.",ar:"لما السقف يسخن $\\Delta T$ عايز يطول $\\alpha\\,\\Delta T$ في كل متر ($\\alpha = 10^{-5}$ لكل درجة). الأعمدة بتمسكه، والإطار بيلاقي نقطة في النص مابتتحركش: كل راس عمود بيتزق لبره $\\alpha\\,\\Delta T\\,x$، و $x$ بعده عن النص ده — $\\Delta$ و $2\\Delta$ و $3\\Delta$… لبره. الأعمدة الطرفية هي اللي بتنحني أكتر، وعزمها بيكبر مع طول المبنى. علشان كده المباني الطويلة بتتقطع لأجزاء أقصاها حوالي **40 م** (بيتقال 40–45 م) بفواصل عرضها حوالي **2 سم**."}},{t:"eq",tex:["\\Delta(x) = \\alpha\\,\\Delta T\\,x,\\qquad \\alpha = 10^{-5}","M \\approx \\dfrac{6EI\\,\\Delta}{h^2}","n = \\left\\lceil \\dfrac{L}{40} \\right\\rceil"],caption:{en:"The moment is that of a column fixed at both ends pushed sideways by Δ (a rigid roof; 3EIΔ/h² for a hinged base) — an upper bound, since the real roof bends too. n = the number of parts of a building L metres long.",ar:"العزم ده بتاع عمود ثابت من الطرفين اتزق جنب Δ (سقف جاسئ؛ و 3EIΔ/h² لركيزة مفصلية) — حد أعلى، لأن السقف الحقيقي بينحني هو كمان. و n = عدد أجزاء مبنى طوله L متر."}},{t:"p",text:{en:"**Example.** A 60 m frame of twelve 5 m bays, 4 m high, columns 300 × 400 ($EI = 22\\times10^6\\times0.0016 = 35200$ kN·m²), roof warming by 30 °C. The end heads move $10^{-5}\\times30\\times30 = 9$ mm; with a rigid roof the end columns would take $6\\times35200\\times0.009/4^2 = 118.8$ kN·m — the lab, with flexible beams, gives 90.2 kN·m. One joint in the middle halves the part: 4.5 mm and 48.8 kN·m (lab); two joints: 3 mm and 33.0 kN·m.",ar:"**مثال.** إطار 60 م من اتناشر باكية 5 م، ارتفاعه 4 م، وأعمدته 300 × 400 ($EI = 22\\times10^6\\times0.0016 = 35200$ kN·m²)، والسقف بيسخن 30 درجة. رؤوس الأطراف بتتحرك $10^{-5}\\times30\\times30 = 9$ مم؛ ولو السقف جاسئ الأعمدة الطرفية كانت هتاخد $6\\times35200\\times0.009/4^2 = 118.8$ kN·m — والمعمل بكمرات مرنة بيدّي 90.2 kN·m. وفاصل واحد في النص بينصّف الجزء: 4.5 مم و 48.8 kN·m (المعمل)؛ وفاصلين: 3 مم و 33.0 kN·m."}},{t:"lab",lab:"frame",height:470,props:{template:"longframe",lockTemplate:!0,missions:o},caption:{en:"Lengthen the frame, add joints, hinge the bases. The Hand method tab gives Δ at the column heads and the end-column moment.",ar:"طوّل الإطار، وزوّد فواصل، وخلّي الركائز مفصلية. وتبويب الحل اليدوي بيدّي Δ عند رؤوس الأعمدة وعزم العمود الطرفي."}},{t:"quiz",q:{kind:"num",q:{en:"A 100 m long building. Into how many parts of at most 40 m is it cut?",ar:"مبنى طوله 100 م. بيتقطع لكام جزء أقصاه 40 م؟"},answer:3,tol:.001,explain:{en:"$\\lceil 100/40 \\rceil = 3$ parts of about 33 m — two joints.",ar:"$\\lceil 100/40 \\rceil = 3$ أجزاء حوالي 33 م — فاصلين."}}}]},{id:"realize",title:{en:"Two ways to build an expansion joint",ar:"طريقتين لتنفيذ فاصل التمدد"},blocks:[{t:"table",head:[{en:"Solution",ar:"الحل"},{en:"How it works",ar:"بيشتغل إزاي"},{en:"For / against",ar:"مميزات / عيوب"}],rows:[[{en:"twin columns",ar:"عمودين توأم"},{en:"each part ends on its own column; the two columns, 2 cm apart, share one footing",ar:"كل جزء بينتهي على عموده؛ والعمودين، بينهم 2 سم، على قاعدة واحدة"},{en:"the simplest to build and to design; costs an extra column line",ar:"الأسهل في التنفيذ والتصميم؛ وبيكلّف خط أعمدة زيادة"}],[{en:"floating bay",ar:"باكية عائمة"},{en:"one bay rests on short cantilevers (corbels) of its neighbours, hinged at one end and sliding at the other",ar:"باكية واحدة راكبة على كوابيل قصيرة من اللي جنبها، مفصلية من طرف ومنزلقة من التاني"},{en:"no extra columns; the corbels and bearings need care",ar:"من غير أعمدة زيادة؛ بس الكوابيل القصيرة والركائز محتاجة عناية"}],[{en:"forked (Y-shaped) column head",ar:"راس عمود متفرّعة (على شكل Y)"},{en:"one column ends in two short cantilevers; the girder on one side sits on a hinge (a dowel through a bearing pad), the girder on the other side on a roller (a pad only), with a 2 cm gap between their ends",ar:"عمود واحد بينتهي بكابولين قصيرين؛ الكمرة اللي من ناحية راكبة على مفصلة (أشاير عابرة لوح ارتكاز)، واللي من الناحية التانية على ركيزة متحركة (لوح بس)، وبين أطرافهم 2 سم"},{en:"one column line and determinate girders — suits weak soil",ar:"خط أعمدة واحد وكمرات محددة — بيناسب التربة الضعيفة"}]]},{t:"p",text:{en:"**On weak soil** a large hall is cut **both ways**: when columns may stand only on lines 30 m apart, a joint runs along every interior column line in each direction, and each 30 × 30 m block stands on its own determinate girders (or tied arch girders) seated on forked heads. **Example:** a 60 × 90 m market on weak soil with column lines every 30 m: one joint line across the 60 m and two across the 90 m give 2 × 3 = 6 blocks of 30 × 30 m. **Where a saw-tooth or an arch slab meets a joint**, the L-shaped beam on each side must turn its horizontal leg **inwards**, away from the gap — or be replaced by a vertical beam alone (usually 400 mm wide) designed for bending about both axes (the saw-tooth episode).",ar:"**على التربة الضعيفة** الصالة الكبيرة بتتقطع **في الاتجاهين**: لما الأعمدة مسموح بيها بس على خطوط بينها 30 م، بيمشي فاصل على كل خط أعمدة داخلي في كل اتجاه، وكل بلوك 30 × 30 م بيقف على كمراته المحددة (أو كمرات مقوّسة بشداد) راكبة على رؤوس متفرّعة. **مثال:** سوق 60 × 90 م على تربة ضعيفة وخطوط الأعمدة كل 30 م: خط فاصل واحد في اتجاه الـ 60 م واتنين في اتجاه الـ 90 م بيدّوا 2 × 3 = 6 بلوكات 30 × 30 م. **ولما سقف منشاري أو بلاطة مقوّسة تقابل فاصل**، الكمرة اللي على شكل L في كل ناحية لازم رجلها الأفقية تبص **لجوه**، بعيد عن الفاصل — أو تتبدّل بكمرة رأسية بس (عرضها غالباً 400 مم) متصممة على عزم في الاتجاهين (حلقة المنشاري)."}},{t:"p",text:{en:"**In a hall of frames** the expansion joint is simply **two complete frames 2 cm apart** — twin frames on twin columns. In a three-hinged hall the 2 cm gap of the crown hinges also runs the whole length of the roof, so the plan shows two double lines. In a saw-tooth hall the joint falls at a valley: twin columns and two end beams back to back. On the drawing sheet the **key plan** (1:200 to 1:400) hatches the part that is drawn and shows every expansion joint as a double line.",ar:"**في صالة إطارات** فاصل التمدد ببساطة **إطارين كاملين بينهم 2 سم** — إطارين توأم على أعمدة توأم. وفي صالة إطارات ثلاثية المفصلات فاصل الـ 2 سم بتاع مفصلات التاج بيمشي هو كمان بطول السقف كله، فالمسقط بيبان فيه خطين مزدوجين. وفي صالة السقف المنشاري الفاصل بييجي عند الوادي: عمودين توأم وكمرتين طرفيتين ضهر لضهر. وفي لوحة الرسم **المسقط المفتاحي (Key plan)** (1:200 لـ 1:400) بيهشّر الجزء المرسوم وبيبيّن كل فاصل تمدد خط مزدوج."}},{t:"p",text:{en:"The lab draws the first two, with the waterproofing and the other joints of this episode. The joint must stay open through every slab, wall and finish above the footing — a single continuous screed is enough to transfer the push.",ar:"المعمل بيرسم أول اتنين، مع العزل والفواصل التانية بتاعة الحلقة دي. والفاصل لازم يفضل مفتوح في كل بلاطة وحائط وتشطيب فوق القاعدة — طبقة ميول واحدة مستمرة كفاية تنقل الزقة."}},{t:"lab",lab:"frame",height:470,props:{template:"longframe",params:{joints:"1"},lockTemplate:!0,defaultTab:"details",missions:s},caption:{en:"The Details tab: twin columns, floating bay, roof and floor joints, settlement and casting joints.",ar:"تبويب التفاصيل: عمودين توأم، وباكية عائمة، وفواصل السطح والأرضية، وفواصل الهبوط والصب."}},{t:"quiz",q:{kind:"mcq",q:{en:"Twin columns of an expansion joint stand on…",ar:"العمودين التوأم بتوع فاصل التمدد واقفين على…"},options:[{en:"one common footing",ar:"قاعدة واحدة مشتركة"},{en:"two separate footings with a 2 cm gap",ar:"قاعدتين منفصلتين بينهم 2 سم"},{en:"a corbel",ar:"كابولي قصير"}],answer:0,explain:{en:"The footing hardly feels the temperature, so one footing serves both columns. Separate footings are for settlement joints.",ar:"القاعدة تقريباً مابتحسش بالحرارة، فقاعدة واحدة بتخدم العمودين. والقواعد المنفصلة لفواصل الهبوط."}}}]},{id:"corbel",title:{en:"The short cantilever of a floating bay",ar:"الكابولي القصير بتاع الباكية العائمة"},blocks:[{t:"p",text:{en:"A corbel is too short to bend like a beam: the load goes down a compression strut to the column while the top bars tie it back — a small truss inside the concrete. It carries the vertical reaction $Q$ of the bay and a horizontal force $P$, the friction of the sliding bearing when the bay moves with temperature (commonly taken as 0.2Q or more). The rules:",ar:"الكابولي القصير أقصر من إنه ينحني زي الكمرة: الحمل بينزل في دعامة ضغط مائلة للعمود والأسياخ اللي فوق بتربطه لورا — جمالون صغير جوه الخرسانة. بيشيل رد الفعل الرأسي $Q$ للباكية وقوة أفقية $P$، احتكاك الركيزة المنزلقة لما الباكية بتتحرك مع الحرارة (غالباً بتتاخد 0.2Q أو أكتر). والقواعد:"}},{t:"steps",items:[{en:"depth at the face of the column $t \\ge a$ (the projection to the load);",ar:"العمق عند وش العمود $t \\ge a$ (المسافة من الوش لحد الحمل)؛"},{en:"depth at the outer edge $\\ge d/2$;",ar:"العمق عند الطرف الخارجي $\\ge d/2$؛"},{en:"main bars on top, anchored into the column and at the outer end (a welded cross bar or a loop);",ar:"الحديد الرئيسي فوق، متثبت جوه العمود وعند الطرف الخارجي (سيخ عرضي ملحوم أو تنية)؛"},{en:"closed horizontal stirrups over the upper 2/3 d, and vertical stirrups;",ar:"كانات أفقية مقفولة في الـ 2/3 d العلوية، وكانات رأسية؛"},{en:"design for $Q$ and $P$ together by the short-bracket clause of ECP 203.",ar:"التصميم على $Q$ و $P$ مع بعض ببند الكوابيل القصيرة في الكود المصري 203."}]},{t:"eq",tex:["M = Q\\,a + P\\,(t - d)","A_s \\approx \\dfrac{M}{0.8\\,d\\,f_y/\\gamma_s} + \\dfrac{P}{f_y/\\gamma_s}"],caption:{en:"A first estimate of the top steel: the tie of a strut-and-tie model with a lever arm of about 0.8d, plus the horizontal force.",ar:"تقدير مبدئي للحديد العلوي: الشداد في نموذج الدعامة والشداد بذراع حوالي 0.8d، زائد القوة الأفقية."}},{t:"p",text:{en:"**Example.** $Q = 250$ kN at $a = 0.25$ m, $P = 0.2Q = 50$ kN; $t = 0.50$ m at the face ($\\ge a$ ✓), $d = 0.45$ m, 0.30 m at the edge ($\\ge d/2 = 0.225$ ✓). $M = 250\\times0.25 + 50\\times0.05 = 65$ kN·m; $A_s = 65/(0.8\\times0.45\\times347.8\\times10^3) + 50/(347.8\\times10^3) = 519.1 + 143.8 = 662.9$ mm² → 6Ø12 (679 mm²), with closed horizontal stirrups over the top 0.30 m.",ar:"**مثال.** $Q = 250$ kN على $a = 0.25$ م، و $P = 0.2Q = 50$ kN؛ و $t = 0.50$ م عند الوش ($\\ge a$ ✓)، و $d = 0.45$ م، و 0.30 م عند الطرف ($\\ge d/2 = 0.225$ ✓). $M = 250\\times0.25 + 50\\times0.05 = 65$ kN·m؛ و $A_s = 65/(0.8\\times0.45\\times347.8\\times10^3) + 50/(347.8\\times10^3) = 519.1 + 143.8 = 662.9$ مم² ← 6Ø12 (679 مم²)، مع كانات أفقية مقفولة في الـ 0.30 م العلوية."}},{t:"quiz",q:{kind:"num",q:{en:"Corbel: Q = 200 kN at a = 0.3 m, P = 40 kN, t − d = 0.05 m. Moment at the face (kN·m)?",ar:"كابولي قصير: Q = 200 kN على a = 0.3 م، و P = 40 kN، و t − d = 0.05 م. العزم عند الوش (kN·m)؟"},answer:62,tol:.003,unit:"kN·m",explain:{en:"$200\\times0.3 + 40\\times0.05 = 60 + 2 = 62$ kN·m.",ar:"$200\\times0.3 + 40\\times0.05 = 60 + 2 = 62$ kN·m."}}}]},{id:"water",title:{en:"Keeping the water out",ar:"منع تسرب المياه"},blocks:[{t:"p",text:{en:"A joint is a 2 cm slot through the whole building, and water finds it. On the **roof** each side gets a raised upstand — about 22 cm high and 10 cm wide — the insulation is turned up against them and a cover (sheet metal or a precast cap) is fixed on **one side only**, so the joint can open and close under it. In **floors and walls** below ground or in wet areas a water-stopper (a PVC strip with a bulb in the gap) or a folded copper plate is cast across the joint, the gap is filled with a compressible filler and sealed on top.",ar:"الفاصل ده شق 2 سم في المبنى كله، والمية بتلاقيه. على **السطح** كل جنب بياخد دروة مرفوعة — حوالي 22 سم ارتفاع و 10 سم عرض — والعزل بيطلع عليها، وغطا (صاج أو غطا سابق الصب) بيتثبت من **ناحية واحدة بس**، علشان الفاصل يفتح ويقفل تحته. وفي **الأرضيات والحوائط** تحت الأرض أو في الأماكن المبلولة بيتصب مانع تسرب (شريط PVC فيه انتفاخ جوه الفاصل) أو لوح نحاس متني عبر الفاصل، والفاصل بيتملي بحشو قابل للانضغاط ومادة عزل فوق."}},{t:"quiz",q:{kind:"tf",q:{en:"The cover over a roof joint is fixed to both upstands so that it cannot be blown off.",ar:"الغطا اللي فوق فاصل السطح بيتثبت في الدروتين علشان الهوا مايشيلوش."},answer:!1,explain:{en:"Fixed on both sides it would be torn by the movement it is meant to allow; it is fixed on one side only.",ar:"لو اتثبت من الناحيتين الحركة اللي المفروض يسمح بيها هتقطعه؛ بيتثبت من ناحية واحدة بس."}}}]},{id:"structural",title:{en:"Structural joints",ar:"الفواصل الإنشائية"},blocks:[{t:"p",text:{en:"Two situations call for a structural joint. **A tall block next to a low one**: they deflect, sway and settle differently, and the connection cracks. **An L- or T-shaped plan**: under wind or an earthquake the load acts at the centre of the area while the plan resists about its centre of rigidity; the two do not coincide, so the building twists and the re-entrant corner cracks. The cure is the same — cut the building into regular rectangles, each with its own stiffness centre on its own centre of mass.",ar:"فيه حالتين محتاجين فاصل إنشائي. **بلوك عالي جنب بلوك واطي**: بيترخّموا ويتحركوا جنب ويهبطوا بشكل مختلف، والوصلة بينهم بتتشرخ. **مسقط على شكل L أو T**: تحت الرياح أو الزلزال الحمل مؤثر عند مركز المساحة والمسقط بيقاوم حوالين مركز الجساءة؛ والاتنين مش منطبقين، فالمبنى بيلتوي والركن الداخلي بيتشرخ. والعلاج واحد — قطّع المبنى لمستطيلات منتظمة، كل واحد مركز جساءته على مركز كتلته."}},{t:"p",text:{en:"**Example:** an L-shaped school with wings 36 × 12 m and 24 × 12 m. One joint along the inner edge of the shorter wing gives a 36 × 12 m block and a 12 × 12 m block — two rectangles, both under 40 m.",ar:"**مثال:** مدرسة على شكل L جناحها 36 × 12 م و 24 × 12 م. فاصل واحد على الحرف الداخلي للجناح الأقصر بيدّي بلوك 36 × 12 م وبلوك 12 × 12 م — مستطيلين، والاتنين أقل من 40 م."}},{t:"p",text:{en:"**A change of system** calls for a structural joint as well. In an L-shaped saw-tooth hall all the glazing must face north, so the two wings run their teeth in different directions — one wing may be of the slab type, the other of the girder type — and the joint between the wings is structural and expansion joint at once.",ar:"**تغيير النظام** محتاج فاصل إنشائي هو كمان. في صالة سقف منشاري على شكل L كل الإزاز لازم يبص للشمال، فالجناحين أسنانهم ماشية في اتجاهين مختلفين — جناح ممكن يبقى نوع البلاطة والتاني نوع الكمرة — والفاصل بين الجناحين بيبقى فاصل إنشائي وفاصل تمدد في نفس الوقت."}},{t:"p",text:{en:"**Where to cut.** Put the joint **in the short direction** — along the shortest line that splits the plan into rectangles. **Example:** an L-shaped hall made of a 36 × 20 m wing and a 16 × 14 m wing: the joint follows the 16 m line where the wings meet, not a 34 m cut through the big wing. The 20 m frames of the big wing that end on that line need a support there. **If columns may stand on the joint line**, a row of columns carries them and nothing more is needed. **If the space must stay open**, a **heavy frame** spanning the 16 m joint line picks up their ends — with frames every 4 m, three of them land on it between its columns (the heavy-frame episode).",ar:"**تقطع فين.** حط الفاصل **في الاتجاه القصير** — على أقصر خط بيقسم المسقط لمستطيلات. **مثال:** صالة على شكل L من جناح 36 × 20 م وجناح 16 × 14 م: الفاصل بيمشي على خط الـ 16 م اللي الجناحين بيتقابلوا عنده، مش قطع 34 م جوه الجناح الكبير. وإطارات الجناح الكبير (بحرها 20 م) اللي بتنتهي على الخط ده محتاجة حاجة تشيلها هناك. **لو مسموح بأعمدة على خط الفاصل**، صف أعمدة بيشيلها ومش محتاجين حاجة تانية. **ولو المكان لازم يفضل مفتوح**، **إطار ثقيل** بحره الـ 16 م على خط الفاصل بيشيل أطرافها — ولو الإطارات كل 4 م، تلاتة منهم بيركبوا عليه بين أعمدته (حلقة الإطار الثقيل)."}},{t:"quiz",q:{kind:"mcq",q:{en:"Why does an L-shaped building twist under wind?",ar:"ليه المبنى اللي على شكل L بيلتوي تحت الرياح؟"},options:[{en:"its centre of mass and its centre of rigidity do not coincide",ar:"مركز كتلته ومركز جساءته مش منطبقين"},{en:"it is longer than 40 m",ar:"طوله أكتر من 40 م"},{en:"its roof expands",ar:"سقفه بيتمدد"}],answer:0,explain:{en:"The force passes through one point and the resistance through another: the eccentric force makes a torsional moment.",ar:"القوة بتعدّي في نقطة والمقاومة في نقطة تانية: القوة اللامركزية بتعمل عزم لي."}}}]},{id:"settlement",title:{en:"Settlement joints and determinate systems",ar:"فواصل الهبوط والأنظمة المحددة"},blocks:[{t:"p",text:{en:"On weak or variable soil the footings will not settle equally. An indeterminate structure resists that and bends; a determinate one moves as a rigid body and keeps its moments. Hence: separate heavy and light parts by settlement joints through the footings, and choose **determinate systems** — three-hinged frames, simple girders, and continuous girders made determinate by **intermediate hinges at about L/5** from a support. That is close to where the continuous beam has no moment anyway (L/4 for two equal spans), so the hinge changes the moments little — and settlement changes them not at all.",ar:"على التربة الضعيفة أو المتغيرة القواعد مش هتهبط بالتساوي. المنشأ غير المحدد بيقاوم ده وبينحني؛ والمحدد بيتحرك كجسم جاسئ ومحافظ على عزومه. يبقى: افصل الأجزاء التقيلة عن الخفيفة بفواصل هبوط عابرة للقواعد، واختار **أنظمة محددة** — إطارات ثلاثية المفصلات، وكمرات بسيطة، وكمرات مستمرة اتعملت محددة بـ**مفصلات وسطية حوالي L/5** من الركيزة. ده قريب من المكان اللي الكمرة المستمرة عزمها فيه صفر أصلاً (L/4 لبحرين متساويين)، فالمفصلة بتغيّر العزوم شوية — والهبوط مابيغيّرهاش خالص."}},{t:"p",text:{en:"**Why determinate.** The bars of a frame are placed where its gravity B.M.D puts the tension: on top at the knees, at the bottom in the span. A settling footing tilts a determinate frame but leaves every moment — and its sign — unchanged, so the bars stay on the tension face. In a fixed frame one settling column adds moments large enough to **reverse** the sign at some sections: the tension moves to the face with almost no bars, and the frame can fail. On weak soil the determinate system is therefore chosen **even when it costs more**. **Example:** a fixed frame 10 m wide and 4 m high (beam 400 × 1000, columns 400 × 800) under 30 kN/m has 179.8 kN·m at both knees and 89.9 kN·m at both bases. Let one footing settle 30 mm: the knee over it turns to −52.3 kN·m — sagging at a beam end that has its bars on top — the other knee climbs to 411.9 kN·m, and the base of the other column reverses (142.2 kN·m the other way). With three hinges the same frame carries more, $wL^2/8 = 375$ kN·m at its knees, but keeps it whatever the footings do.",ar:"**ليه المحدد.** حديد الإطار بيتحط في المكان اللي منحنى عزوم الأحمال الرأسية بيحط فيه الشد: فوق عند الأركان، وتحت في البحر. والقاعدة اللي بتهبط بتميّل الإطار المحدد بس بتسيب كل عزم — وإشارته — زي ما هو، فالحديد بيفضل على وش الشد. وفي الإطار ثابت الركائز عمود واحد بيهبط بيزوّد عزوم كبيرة كفاية إنها **تعكس** الإشارة في قطاعات: الشد بيروح للوش اللي تقريباً مفيهوش حديد، والإطار ممكن ينهار. علشان كده على التربة الضعيفة النظام المحدد بيتختار **حتى لو أغلى**. **مثال:** إطار ثابت الركائز عرضه 10 م وارتفاعه 4 م (الكمرة 400 × 1000، والأعمدة 400 × 800) تحت 30 kN/m عليه 179.8 kN·m عند الركنين و 89.9 kN·m عند القاعدتين. خلّي قاعدة واحدة تهبط 30 مم: الركن اللي فوقها بيقلب لـ −52.3 kN·m — عزم موجب عند طرف كمرة حديده فوق — والركن التاني بيطلع لـ 411.9 kN·m، وقاعدة العمود التاني بتعكس (142.2 kN·m في الاتجاه التاني). وبتلات مفصلات نفس الإطار بيشيل أكتر، $wL^2/8 = 375$ kN·m عند أركانه، بس بيحافظ عليه مهما القواعد عملت."}},{t:"p",text:{en:"**Example.** Two 12 m spans on a 300 × 900 beam ($EI = 22\\times10^6\\times0.018225 = 400950$ kN·m²), 30 kN/m. Continuous: $M_B = wL^2/8 = 540$ kN·m; if the middle support sinks 40 mm, $M_B$ loses $3EI\\Delta/L^2 = 3\\times400950\\times0.04/144 = 334.1$ kN·m and drops to 205.9 kN·m — the spans must now carry the difference. With a hinge 2.4 m ($L/5$) into the second span: the suspended 9.6 m hangs 144 kN on a 2.4 m cantilever, $M_B = 144\\times2.4 + 30\\times2.4^2/2 = 432$ kN·m, settlement or not. A **bridge between two buildings** follows the same logic: it is simply supported on short cantilevers of both, hinged at one end and sliding at the other.",ar:"**مثال.** بحرين 12 م على كمرة 300 × 900 ($EI = 22\\times10^6\\times0.018225 = 400950$ kN·m²)، و 30 kN/m. مستمرة: $M_B = wL^2/8 = 540$ kN·m؛ ولو الركيزة الوسطية هبطت 40 مم، $M_B$ بيخسر $3EI\\Delta/L^2 = 3\\times400950\\times0.04/144 = 334.1$ kN·m وبينزل لـ 205.9 kN·m — والبحور لازم تشيل الفرق. وبمفصلة على بعد 2.4 م ($L/5$) جوه البحر التاني: الجزء المعلّق 9.6 م بيعلّق 144 kN على كابولي 2.4 م، $M_B = 144\\times2.4 + 30\\times2.4^2/2 = 432$ kN·m، هبطت أو ماهبطتش. و**الكوبري بين مبنيين** ماشي بنفس المنطق: بسيط الارتكاز على كوابيل قصيرة من الاتنين، مفصلي من طرف ومنزلق من التاني."}},{t:"p",text:{en:"**A step in height is not enough by itself.** A settlement joint between two parts of different heights is needed only when the difference is large — about **6–8 m**. A step of about 3 m between two roof levels needs none: the two roofs simply meet on one column line.",ar:"**فرق الارتفاع لوحده مش كفاية.** فاصل الهبوط بين جزئين بارتفاعات مختلفة مطلوب بس لما الفرق يبقى كبير — حوالي **6–8 م**. ودرجة حوالي 3 م بين منسوبين سقف مش محتاجة فاصل: السقفين بيتقابلوا على خط أعمدة واحد وخلاص."}},{t:"lab",lab:"frame",height:470,props:{template:"settle",params:{sys:"cont",L:12,w:30,d:0},lockTemplate:!0,missions:i},caption:{en:"Two 12 m spans: settle the middle support, then put a hinge at L/5 and settle it again.",ar:"بحرين 12 م: نزّل الركيزة الوسطية، وبعدين حط مفصلة عند L/5 ونزّلها تاني."}},{t:"quiz",q:{kind:"tf",q:{en:"A two-span girder with a hinge at L/5 changes its moments when its middle support settles.",ar:"كمرة ببحرين ومفصلة عند L/5 عزومها بتتغيّر لما ركيزتها الوسطية تهبط."},answer:!1,explain:{en:"The hinge makes it determinate: the settlement only turns its parts as rigid bodies.",ar:"المفصلة بتخليها محددة: الهبوط بيلف أجزاءها كأجسام جاسئة بس."}}}]},{id:"step",title:{en:"A step in the roof: two roofs on one column line",ar:"درجة في السقف: سقفين على خط أعمدة واحد"},blocks:[{t:"p",text:{en:"Where the roof steps down by a few metres and no joint is needed, the two roofs meet on **one line of columns**. How they meet depends on the two systems:",ar:"لما السقف ينزل درجة كام متر ومش محتاجين فاصل، السقفين بيتقابلوا على **خط أعمدة واحد**. وإزاي بيتقابلوا ده بيعتمد على النظامين:"}},{t:"steps",items:[{en:"**Two girders.** Each stays a simple girder. The shared column carries the upper girder at its head and the lower one part-way down, so its normal force grows from $R_1$ above the lower girder to $R_1 + R_2$ below it — $2R$ for two equal girders. The column continues up between the two roofs (the band of glazing), and the bars of both girders are hooked into it.",ar:"**كمرتين.** كل واحدة بتفضل كمرة بسيطة. والعمود المشترك شايل الكمرة العالية عند راسه والواطية في نصه تقريباً، فقوته العمودية بتزيد من $R_1$ فوق الكمرة الواطية لـ $R_1 + R_2$ تحتها — يعني $2R$ لكمرتين زي بعض. والعمود بيكمّل لفوق بين السقفين (شريط الإزاز)، وحديد الكمرتين بيخلص بجنش جواه."},{en:"**A girder and a frame.** The girder stays simple and rests on the frame column: its reaction is an axial load on that column at the lower level. The girder's other column, hinged at its head, receives no moment. The girder bars run into the frame column and end in hooks. This is the usual roof of an **annex** beside a hall: a simple girder, $L/10$ deep, seated on the hall's frame columns; a small lantern raised on the annex roof is a light box on short posts standing on that girder.",ar:"**كمرة وإطار.** الكمرة بتفضل بسيطة وراكبة على عمود الإطار: رد فعلها حمل محوري على العمود ده عند المنسوب الواطي. والعمود التاني بتاع الكمرة، مفصلي عند راسه، مابياخدش عزم. وحديد الكمرة بيدخل عمود الإطار وبيخلص بجنش. وده السقف المعتاد لـ**مبنى ملحق** جنب صالة: كمرة بسيطة، عمقها $L/10$، راكبة على أعمدة إطارات الصالة؛ والشخشيخة الصغيرة المرفوعة على سقف الملحق صندوق خفيف على قوائم قصيرة واقفة على الكمرة دي."},{en:"**Two frames.** On site the pair is usually built and solved as one continuous frame; by hand it is far easier to separate them. The **tall frame** is two-hinged (moment distribution); the **low frame** is **roller–fixed** (virtual work, the heavy-frame episode): its beam end is dapped and seated on a sliding bearing on a **short cantilever (corbel)** of the tall column, and its far column is fixed and prismatic. The tall frame then carries the roller reaction $R$ on its column at the corbel level, and the corbel is designed for $Q = R$ with the friction $P$ (above): a looped top bar, closed ties, inclined bars and dense stirrups in the nib.",ar:"**إطارين.** في الموقع الاتنين غالباً بيتنفذوا ويتحلوا كإطار مستمر واحد؛ وباليد أسهل بكتير تفصلهم. **الإطار العالي** ذو مفصلين (توزيع العزوم)؛ و**الإطار الواطي** على **ركيزة متحركة وثابتة** (الشغل الافتراضي، حلقة الإطار الثقيل): طرف كمرته متدرّج (Dapped end) وراكب على ركيزة منزلقة فوق **كابولي قصير** من العمود العالي، وعموده البعيد ثابت ومنتظم القطاع. والإطار العالي ساعتها بيشيل رد فعل الركيزة المتحركة $R$ على عموده عند منسوب الكابولي القصير، والكابولي القصير بيتصمم على $Q = R$ مع الاحتكاك $P$ (فوق): سيخ علوي على شكل فيونكة (Loop)، وكانات مقفولة، وأسياخ مكسحة، وكانات كتيرة في الكتف."}]},{t:"p",text:{en:"**Example.** An upper girder of 12 m (40 kN/m) and a lower one of 8 m (35 kN/m), $L/10 = 1.20$ and 0.80 m deep, share a column: $R_1 = 40\\times12/2 = 240$ kN at its head, $R_2 = 35\\times8/2 = 140$ kN part-way down → 380 kN at its base. A low roller–fixed frame of 15 m (beam 400 × 1100, fixed column 400 × 800 and 4 m high, $w = 40$ kN/m) gives $R = 275.7$ kN at the roller and 365.3 kN·m at its knee — the same all the way down its column, since nothing pushes it sideways — and 949.8 kN·m in its span. The corbel of the tall column: $Q = 275.7$ kN at $a = 0.30$ m, $P = 0.2Q = 55.1$ kN, $t = 0.60$ m ($d = 0.55$ m), 0.35 m at its edge: $M = 275.7\\times0.30 + 55.1\\times0.05 = 85.5$ kN·m, $A_s = 558.3 + 158.5 = 716.8$ mm² → 4Ø16 (804 mm²).",ar:"**مثال.** كمرة عالية 12 م (40 kN/m) وكمرة واطية 8 م (35 kN/m)، عمقهم $L/10 = 1.20$ و 0.80 م، بيشتركوا في عمود: $R_1 = 40\\times12/2 = 240$ kN عند راسه، و $R_2 = 35\\times8/2 = 140$ kN في نصه ← 380 kN عند قاعدته. وإطار واطي على ركيزة متحركة وثابتة بحره 15 م (الكمرة 400 × 1100، والعمود الثابت 400 × 800 وارتفاعه 4 م، و $w = 40$ kN/m) بيدّي $R = 275.7$ kN عند الركيزة المتحركة و 365.3 kN·m عند ركنه — نفس القيمة على طول عموده، لأن مفيش حاجة بتزقه جنب — و 949.8 kN·m في بحره. والكابولي القصير بتاع العمود العالي: $Q = 275.7$ kN على $a = 0.30$ م، و $P = 0.2Q = 55.1$ kN، و $t = 0.60$ م ($d = 0.55$ م)، و 0.35 م عند طرفه: $M = 275.7\\times0.30 + 55.1\\times0.05 = 85.5$ kN·m، و $A_s = 558.3 + 158.5 = 716.8$ مم² ← 4Ø16 (804 مم²)."}},{t:"quiz",q:{kind:"num",q:{en:"At a roof step a shared column carries an upper girder reaction of 260 kN at its head and a lower girder reaction of 180 kN part-way down. Normal force at its base (kN)?",ar:"عند درجة في السقف عمود مشترك شايل رد فعل كمرة عالية 260 kN عند راسه ورد فعل كمرة واطية 180 kN في نصه. القوة العمودية عند قاعدته (kN)؟"},answer:440,tol:.003,unit:"kN",explain:{en:"$260 + 180 = 440$ kN below the lower girder; 260 kN above it.",ar:"$260 + 180 = 440$ kN تحت الكمرة الواطية؛ و 260 kN فوقها."}}}]},{id:"determinate",title:{en:"Weak soil or a large temperature difference: externally determinate systems",ar:"تربة ضعيفة أو فرق حرارة كبير: أنظمة محددة خارجياً"},blocks:[{t:"p",text:{en:"Two conditions call for systems that are **externally determinate** — supports that do not fight a movement: **weak soil**, which settles unequally, and a **large temperature difference between inside and outside** (a cold store, a furnace hall), which makes the members grow or shrink against their supports. Each determinate family has its reach:",ar:"فيه حالتين محتاجين أنظمة **محددة خارجياً** — ركائز مابتقاومش الحركة: **التربة الضعيفة**، اللي بتهبط بشكل مش متساوي، و**فرق الحرارة الكبير بين جوه وبره** (ثلاجة تخزين أو صالة أفران)، اللي بيخلّي الأعضاء تطول أو تقصر ضد ركائزها. وكل عيلة محددة ليها مداها:"}},{t:"table",head:[{en:"System",ar:"النظام"},{en:"Supports",ar:"الركائز"},{en:"Span up to",ar:"البحر لحد"}],rows:[[{en:"simple girder",ar:"كمرة بسيطة"},{en:"hinge + roller (or columns acting as hinges)",ar:"مفصلة + ركيزة متحركة (أو أعمدة شغالة مفصلات)"},"12 m"],[{en:"three-hinged frame",ar:"إطار ثلاثي المفصلات"},{en:"two footing hinges + a crown hinge",ar:"مفصلتين عند القواعد + مفصلة التاج"},"16 m"],[{en:"polygon frame (triangular / trapezoidal)",ar:"إطار مضلع (مثلثي / شبه منحرف)"},{en:"hinge + roller, tied",ar:"مفصلة + ركيزة متحركة، بشداد"},"24 m"],[{en:"arch girder",ar:"كمرة مقوّسة"},{en:"hinge + roller, tied",ar:"مفصلة + ركيزة متحركة، بشداد"},"40 m"],[{en:"truss",ar:"جمالون"},{en:"hinge + roller",ar:"مفصلة + ركيزة متحركة"},"40 m"]],caption:{en:"Beyond 24 m a simply supported roof becomes an arch girder; a beam with a cantilever beyond 24 m (say 32 m with an 8 m overhang) must be a truss, its panels continuing over the cantilever. Three-hinged frames cover 12–16 m, on weak soil too (the frames episode); beyond 16 m the tied polygon frame on a hinge and a roller takes over, up to 24 m.",ar:"بعد 24 م السقف البسيط بيبقى كمرة مقوّسة؛ والكمرة بكابولي بعد 24 م (مثلاً 32 م وكابولي 8 م) لازم تبقى جمالون، وبواكيه بتكمّل على الكابولي. والإطارات ثلاثية المفصلات بتغطي من 12 لـ 16 م، وعلى التربة الضعيفة كمان (حلقة الإطارات)؛ وبعد 16 م الإطار المضلع بشداد على مفصلة وركيزة متحركة بياخد مكانها، لحد 24 م."}},{t:"p",text:{en:"**Example** — a cold store on weak soil, by span: 11 m → a simple girder on its columns; 15 m → a three-hinged frame; 22 m → a tied polygon frame on a hinge and a roller; 34 m → a tied arch girder or a truss; 28 m with a 9 m canopy → a truss.",ar:"**مثال** — ثلاجة تخزين على تربة ضعيفة، حسب البحر: 11 م ← كمرة بسيطة على أعمدتها؛ و 15 م ← إطار ثلاثي المفصلات؛ و 22 م ← إطار مضلع بشداد على مفصلة وركيزة متحركة؛ و 34 م ← كمرة مقوّسة بشداد أو جمالون؛ و 28 م بمظلة 9 م ← جمالون."}},{t:"quiz",q:{kind:"mcq",q:{en:"A 20 m hall on weak soil. Which externally determinate system?",ar:"صالة 20 م على تربة ضعيفة. أنهي نظام محدد خارجياً؟"},options:[{en:"a tied polygon frame on a hinge and a roller",ar:"إطار مضلع بشداد على مفصلة وركيزة متحركة"},{en:"a girder continuous over its columns",ar:"كمرة مستمرة على أعمدتها"},{en:"a fixed-base frame",ar:"إطار ثابت الركائز"}],answer:0,explain:{en:"The tied polygon frame on a hinge and a roller is externally determinate up to 24 m. A continuous girder (which stops at 12 m anyway) and a fixed-base frame are indeterminate: a settling footing would change their moments.",ar:"الإطار المضلع بشداد على مفصلة وركيزة متحركة محدد خارجياً لحد 24 م. والكمرة المستمرة (اللي أصلاً بتقف عند 12 م) والإطار ثابت الركائز غير محددين: القاعدة اللي بتهبط هتغيّر عزومهم."}}}]},{id:"corridor",title:{en:"A floating corridor beside a tall block",ar:"ممر عائم جنب مبنى عالي"},blocks:[{t:"p",text:{en:"A hall built next to a tall block — a factory beside its office tower, a workshop beside a multi-storey building — is often joined to it by a covered **corridor**. The two will settle and sway differently, so the corridor must not tie them together: it is a **floating bay**. Its slab is carried by **floating beams** spanning across the corridor, one on every frame line of the hall. Each beam is simply supported — hinged at one end, sliding at the other — and its **dapped ends** sit on **short cantilevers (corbels)**: one on the hall's frame column, one on the column of the block. The slab spans along the corridor between the floating beams, continuous over them — a solid slab about $S/30$ thick, or a ribbed one.",ar:"الصالة اللي بتتبني جنب مبنى عالي — مصنع جنب مبنى إدارته، أو ورشة جنب مبنى متعدد الأدوار — غالباً بتتوصل بيه بـ**ممر** مسقوف. والاتنين هيهبطوا ويتحركوا جنب بشكل مختلف، فالممر لازم مايربطهمش ببعض: هو **باكية عائمة**. بلاطته شايلاها **كمرات عائمة** بحرها عرض الممر، واحدة على كل خط إطار في الصالة. وكل كمرة بسيطة الارتكاز — مفصلية من طرف ومنزلقة من التاني — وأطرافها **المتدرّجة (Dapped end)** راكبة على **كوابيل قصيرة**: واحد في عمود إطار الصالة، وواحد في عمود المبنى. والبلاطة بحرها بطول الممر بين الكمرات العائمة، مستمرة عليهم — بلاطة مصمتة تخانتها حوالي $S/30$، أو بلاطة هوردي."}},{t:"steps",items:[{en:"**The floating beam.** $w = o.w. + w_s\\,S$ — the slab from half a bay on each side, $S$ being the spacing of the frames; $M = wL^2/8$ on a T-section in the span (a rectangle under a ribbed slab), its flange $B = \\min(S,\\ 16\\,t_s + b,\\ L/5 + b)$ — a simple beam, $K = 1.0$ (the girders episode); $Q = wL/2$ at each end.",ar:"**الكمرة العائمة.** $w = o.w. + w_s\\,S$ — البلاطة من نص باكية من كل ناحية، و $S$ المسافة بين الإطارات؛ و $M = wL^2/8$ على قطاع T في البحر (وقطاع مستطيل تحت بلاطة هوردي)، وشفته $B = \\min(S,\\ 16\\,t_s + b,\\ L/5 + b)$ — كمرة بسيطة، $K = 1.0$ (حلقة الكمرات)؛ و $Q = wL/2$ عند كل طرف."},{en:"**The nib.** About half the depth of the beam. Check $q_u = Q/(b\\,d)$ with the **nib's** $d$ against $q_{u,max} = 0.7\\sqrt{f_{cu}/\\gamma_c}$. The concrete carries $q_{cu} = 0.16\\sqrt{f_{cu}/\\gamma_c}$ uncracked and keeps $q_{cu,cr} = 0.12\\sqrt{f_{cu}/\\gamma_c}$ once cracked: whenever $q_u > q_{cu,cr}$ the stirrups take $q_s = q_u - q_{cu,cr}$ at a spacing $s = n\\,A_\\phi\\,(f_{yst}/\\gamma_s)/(b\\,q_s)$ of at least 100 mm: try Ø8 with two branches, then Ø10, then Ø8 with four branches. When that gives fewer than 5 per metre, the minimum 5Ø8/m′ governs — usually the case along the rest of the beam, where $d$ is the full depth. (Some designers use $0.24\\sqrt{f_{cu}/\\gamma_c}$, 0.98 N/mm² for $f_{cu} = 25$, as the boundary and deduct half of it — the same 0.49.)",ar:"**الكتف (Nib).** عمقه حوالي نص عمق الكمرة. راجع $q_u = Q/(b\\,d)$ بالـ $d$ بتاعة **الكتف** قصاد $q_{u,max} = 0.7\\sqrt{f_{cu}/\\gamma_c}$. والخرسانة بتشيل $q_{cu} = 0.16\\sqrt{f_{cu}/\\gamma_c}$ وهي غير مشرخة، وبتحتفظ بـ $q_{cu,cr} = 0.12\\sqrt{f_{cu}/\\gamma_c}$ بعد ما تشرخ: ولما $q_u > q_{cu,cr}$ الكانات بتشيل $q_s = q_u - q_{cu,cr}$ على مسافة $s = n\\,A_\\phi\\,(f_{yst}/\\gamma_s)/(b\\,q_s)$ مش أقل من 100 مم: جرّب Ø8 بفرعين، وبعدين Ø10، وبعدين Ø8 بأربع فروع. ولو ده طلّع أقل من 5 في المتر، الحد الأدنى 5Ø8/م′ هو اللي بيحكم — وده غالباً اللي بيحصل في باقي الكمرة، لأن $d$ هناك العمق الكامل. (فيه مصممين بيستخدموا $0.24\\sqrt{f_{cu}/\\gamma_c}$، يعني 0.98 N/mm² لـ $f_{cu} = 25$، كحد فاصل، وبيطرحوا نصها — نفس الـ 0.49.)"},{en:"**The bars.** Part of the bottom steel runs straight to the end of the nib, the rest is bent up at 45° into its top; top hanger bars, and stirrup hangers grouped at the re-entrant corner.",ar:"**الحديد.** جزء من الحديد السفلي بيمشي مستقيم لآخر الكتف، والباقي بيتكسح لفوق بزاوية 45° جوه أعلاه؛ وحديد تعليق فوق، وكانات تعليق متجمعة عند الركن الداخلي."},{en:"**The hall column** receives $Q$ at its corbel: its normal force grows by $Q$ below the corbel — add it to the N.F.D — and the corbel is designed for $Q$ with the friction $P = 0.2Q$ (the corbel above).",ar:"**عمود الصالة** بياخد $Q$ عند الكابولي القصير بتاعه: قوته العمودية بتزيد بـ $Q$ تحت الكابولي — زوّدها في منحنى القوى العمودية — والكابولي القصير بيتصمم على $Q$ مع الاحتكاك $P = 0.2Q$ (الكابولي القصير اللي فوق)."}]},{t:"p",text:{en:"**Example** ($f_{cu} = 25$, $f_y = 400$, stirrups of mild steel 240). A corridor 4.5 m wide beside a hall whose frames are 5.5 m apart. The slab spans 5.5 m between the floating beams: $t_s = 5500/30 = 183 \\to 190$ mm; with finishes 1.0 and live load 2.0 kN/m², $w_s = 1.4\\times(0.19\\times25 + 1.0) + 1.6\\times2.0 = 11.25$ kN/m². Floating beams 300 × 700: $w = 1.4\\times0.3\\times0.7\\times25 + 11.25\\times5.5 = 7.35 + 61.88 = 69.23$ kN/m, $M = 69.23\\times4.5^2/8 = 175.2$ kN·m, $Q = 69.23\\times4.5/2 = 155.8$ kN. Nib 350 deep ($d = 300$): $q_u = 155.8\\times10^3/(300\\times300) = 1.73$ N/mm², above $q_{cu,cr} = 0.49$ (and $q_{cu} = 0.653$), below $q_{u,max} = 2.86$ → $q_s = 1.73 - 0.49 = 1.24$ N/mm². Ø8 with two branches: $s = 56.4$ mm ✗; Ø10 with two branches: $s = 88.1$ mm ✗; Ø8 with four branches: $s = 112.7$ mm ✓ → $1000/112.7 = 8.9$ → 9Ø8/m with four branches near the ends, 5Ø8/m in between (beyond the nib $q_u = 155.8\\times10^3/(300\\times650) = 0.80$ N/mm², $q_s = 0.31$: Ø8 with two branches at 226 mm, 4.4 per metre — fewer than 5, so the minimum governs). Below its corbel the hall column carries 155.8 kN more. In its span the beam is a T-section ($d = 650$ mm): $B = \\min(5500,\\ 16\\times190 + 300 = 3340,\\ 4500/5 + 300 = 1200) = 1200$ mm; $C_1 = 650/\\sqrt{175.2\\times10^6/(25\\times1200)} = 8.51$ → $J = 0.826$, $A_s = 816$ mm², above $\\mu_{min}\\,b\\,d = 0.225\\sqrt{25}/400\\times300\\times650 = 548$ mm² → 4Ø18 (1018 mm²) in one row — two of them run straight to the end of the nib, two are bent up into it.",ar:"**مثال** ($f_{cu} = 25$، و $f_y = 400$، والكانات حديد طري 240). ممر عرضه 4.5 م جنب صالة إطاراتها كل 5.5 م. والبلاطة بحرها 5.5 م بين الكمرات العائمة: $t_s = 5500/30 = 183 \\to 190$ مم؛ وبتشطيبات 1.0 وحمل حي 2.0 kN/m²، $w_s = 1.4\\times(0.19\\times25 + 1.0) + 1.6\\times2.0 = 11.25$ kN/m². والكمرات العائمة 300 × 700: $w = 1.4\\times0.3\\times0.7\\times25 + 11.25\\times5.5 = 7.35 + 61.88 = 69.23$ kN/m، و $M = 69.23\\times4.5^2/8 = 175.2$ kN·m، و $Q = 69.23\\times4.5/2 = 155.8$ kN. والكتف عمقه 350 ($d = 300$): $q_u = 155.8\\times10^3/(300\\times300) = 1.73$ N/mm²، أكبر من $q_{cu,cr} = 0.49$ (ومن $q_{cu} = 0.653$) وأقل من $q_{u,max} = 2.86$ ← $q_s = 1.73 - 0.49 = 1.24$ N/mm². Ø8 بفرعين: $s = 56.4$ مم ✗؛ و Ø10 بفرعين: $s = 88.1$ مم ✗؛ و Ø8 بأربع فروع: $s = 112.7$ مم ✓ ← $1000/112.7 = 8.9$ ← 9Ø8/م بأربع فروع قرب الأطراف، و 5Ø8/م في النص (بعد الكتف $q_u = 155.8\\times10^3/(300\\times650) = 0.80$ N/mm²، و $q_s = 0.31$: Ø8 بفرعين كل 226 مم، يعني 4.4 في المتر — أقل من 5، فالحد الأدنى هو اللي بيحكم). وتحت الكابولي القصير عمود الصالة بيشيل 155.8 kN زيادة. وفي بحرها الكمرة قطاع T ($d = 650$ مم): $B = \\min(5500,\\ 16\\times190 + 300 = 3340,\\ 4500/5 + 300 = 1200) = 1200$ مم؛ و $C_1 = 650/\\sqrt{175.2\\times10^6/(25\\times1200)} = 8.51$ ← $J = 0.826$، و $A_s = 816$ مم²، أكبر من $\\mu_{min}\\,b\\,d = 0.225\\sqrt{25}/400\\times300\\times650 = 548$ مم² ← 4Ø18 (1018 مم²) في صف واحد — اتنين منهم بيمشوا مستقيم لآخر الكتف، واتنين بيتكسحوا لفوق جواه."}},{t:"quiz",q:{kind:"num",q:{en:"A floating corridor beam 250 × 600 spans 5.0 m and carries 7.5 kN/m² of slab from 2.5 m on each side, plus its own weight 1.4 × 0.25 × 0.6 × 25. Reaction on each corbel (kN)?",ar:"كمرة ممر عائم 250 × 600 بحرها 5.0 م وشايلة بلاطة 7.5 kN/m² من 2.5 م من كل ناحية، زائد وزنها 1.4 × 0.25 × 0.6 × 25. رد الفعل على كل كابولي قصير (kN)؟"},answer:106.875,tol:.003,unit:"kN",explain:{en:"$w = 5.25 + 2\\times7.5\\times2.5 = 42.75$ kN/m → $Q = 42.75\\times5.0/2 = 106.9$ kN (and $M = 42.75\\times5^2/8 = 133.6$ kN·m in the span).",ar:"$w = 5.25 + 2\\times7.5\\times2.5 = 42.75$ kN/m ← $Q = 42.75\\times5.0/2 = 106.9$ kN (و $M = 42.75\\times5^2/8 = 133.6$ kN·m في البحر)."}}}]},{id:"bridges",title:{en:"Longer links: bridges between buildings",ar:"وصلات أطول: الكباري بين المباني"},blocks:[{t:"p",text:{en:"A bridge between two buildings must be **determinate — a hinge at one end and a roller at the other** — so that a differential settlement of the two buildings moves it without breaking it. A short link sits on corbels (the corbel above, and your building below). A longer one is still a **floating bay**; only its member changes with the span:",ar:"الكوبري بين مبنيين لازم يبقى **محدد — مفصلة من طرف وركيزة متحركة من التاني** — علشان الهبوط النسبي بين المبنيين يحرّكه من غير ما يكسره. الوصلة القصيرة بتركب على كوابيل قصيرة (الكابولي القصير اللي فوق، ومبناك تحت). والأطول برضه **باكية عائمة**؛ بس العضو هو اللي بيتغيّر مع البحر:"}},{t:"steps",items:[{en:"**About 20 m — a simple girder.** Two main girders ($t = L/10$) with cross beams, the walking slab level with the floors. Each end is **dapped**: it ends in a nib about half the depth, seated on a bearing on a short cantilever of the building column. The nib is the weak point: **check the shear at its reduced section**, bend the main bottom bars up at 45° into its top and anchor them, add horizontal U-loops in it, and group **stirrup hangers** at the re-entrant corner so they lift the whole reaction into the full-depth girder.",ar:"**حوالي 20 م — كمرة بسيطة.** كمرتين رئيسيتين ($t = L/10$) وكمرات عرضية، وبلاطة المشي على منسوب الأدوار. وكل طرف **متدرّج (Dapped end)**: بينتهي بكتف (Nib) عمقه حوالي النص، راكب على لوح ارتكاز فوق كابولي قصير من عمود المبنى. والكتف هو نقطة الضعف: **راجع القص عند قطاعه المنقوص**، واكسح الحديد السفلي الرئيسي لفوق بزاوية 45° جوه أعلاه وثبّته، وزوّد تنيات أفقية على شكل U جواه، وجمّع **كانات تعليق** عند الركن الداخلي علشان ترفع رد الفعل كله للكمرة بعمقها الكامل."},{en:"**About 30 m — a tied arch girder.** A girder 3 m deep would be heavy; an arch girder on a hinge and a roller does the job, but its rise is set by the storey of the bridge — about 3 m, $L/10$, flatter than the usual $L/8$–$L/6$, so its tie works harder ($T \\propto 1/h$). A pedestrian bridge then has a **lower slab** at the tie level to walk on and an **upper slab** at the top chord as a cover — or the lower slab only.",ar:"**حوالي 30 م — كمرة مقوّسة بشداد.** كمرة عمقها 3 م هتبقى تقيلة؛ والكمرة المقوّسة على مفصلة وركيزة متحركة بتعمل الشغلانة، بس ارتفاعها بيحدده دور الكوبري — حوالي 3 م، يعني $L/10$، أوطى من المعتاد $L/8$–$L/6$، فشدادها بيشتغل أكتر ($T \\propto 1/h$). وكوبري المشاة ساعتها فيه **بلاطة سفلية** عند منسوب الشداد للمشي عليها و**بلاطة علوية** عند الوتر العلوي كتغطية — أو البلاطة السفلية بس."}]},{t:"p",text:{en:"**Example.** An 18 m footbridge: two girders 400 × 1800 ($18/10$) 4.0 m apart, a 150 mm slab, finishes 1.5 and crowd 5.0 kN/m². Per girder: $1.4\\times0.4\\times1.8\\times25 + 1.4\\times5.25\\times2.0 + 1.6\\times5.0\\times2.0 = 25.2 + 14.7 + 16.0 = 55.9$ kN/m → $Q = 55.9\\times9 = 503.1$ kN. Nib 900 mm deep ($d = 850$ mm): $q_u = 503.1\\times10^3/(400\\times850) = 1.48$ N/mm² below $q_{u,max} = 0.7\\sqrt{30/1.5} = 3.13$ N/mm² ($f_{cu} = 30$) ✓; stirrup hangers $503.1\\times10^3/347.8 = 1446$ mm² → five closed two-leg Ø14 (1539 mm²). Over 32 m with a 3.2 m storey: an arch girder of rise 3.2 m ($L/10$) with joint loads of 220 kN every 4 m: $M_0 = 32\\times220 = 7040$ kN·m, $T = 0.95\\times7040/3.2 = 2090$ kN — against 1672 kN with the usual $L/8 = 4.0$ m — and $A_s = 6009$ mm² in the tie.",ar:"**مثال.** كوبري مشاة 18 م: كمرتين 400 × 1800 ($18/10$) بينهم 4.0 م، وبلاطة 150 مم، وتشطيبات 1.5 وزحمة 5.0 kN/m². لكل كمرة: $1.4\\times0.4\\times1.8\\times25 + 1.4\\times5.25\\times2.0 + 1.6\\times5.0\\times2.0 = 25.2 + 14.7 + 16.0 = 55.9$ kN/m ← $Q = 55.9\\times9 = 503.1$ kN. والكتف عمقه 900 مم ($d = 850$ مم): $q_u = 503.1\\times10^3/(400\\times850) = 1.48$ N/mm² أقل من $q_{u,max} = 0.7\\sqrt{30/1.5} = 3.13$ N/mm² ($f_{cu} = 30$) ✓؛ وكانات التعليق $503.1\\times10^3/347.8 = 1446$ مم² ← خمس كانات مقفولة بفرعين Ø14 (1539 مم²). وعلى 32 م بدور ارتفاعه 3.2 م: كمرة مقوّسة ارتفاعها 3.2 م ($L/10$) وأحمال عقدها 220 kN كل 4 م: $M_0 = 32\\times220 = 7040$ kN·m، و $T = 0.95\\times7040/3.2 = 2090$ kN — قصاد 1672 kN بالمعتاد $L/8 = 4.0$ م — و $A_s = 6009$ مم² في الشداد."}},{t:"quiz",q:{kind:"num",q:{en:"A footbridge girder hands Q = 450 kN to a nib 350 mm wide with d = 800 mm. Shear stress at the nib (N/mm²)?",ar:"كمرة كوبري مشاة بتسلّم Q = 450 kN لكتف عرضه 350 مم و d = 800 مم. إجهاد القص عند الكتف (N/mm²)؟"},answer:1.607,tol:.003,unit:"N/mm²",explain:{en:"$450\\times10^3/(350\\times800) = 1.61$ N/mm², well below $q_{u,max} = 3.13$ N/mm² for $f_{cu} = 30$.",ar:"$450\\times10^3/(350\\times800) = 1.61$ N/mm²، أقل بكتير من $q_{u,max} = 3.13$ N/mm² لـ $f_{cu} = 30$."}}}]},{id:"casting",title:{en:"Casting joints",ar:"فواصل الصب"},blocks:[{t:"steps",items:[{en:"Stop casting where the shear and the moment are small — about **L/5** from a support of a continuous beam or slab.",ar:"وقّف الصب في المكان اللي القص والعزم فيه صغيرين — حوالي **L/5** من ركيزة الكمرة أو البلاطة المستمرة."},{en:"The part already cast must be stable on its own (a cantilever stub, not a beam hanging in the air).",ar:"الجزء اللي اتصب لازم يبقى مستقر لوحده (جزء كابولي، مش كمرة متعلقة في الهوا)."},{en:"Leave the face rough and inclined at about 45°, clean it and wet it before the next pour, so the new concrete keys into the old.",ar:"سيب الوش خشن ومايل حوالي 45°، ونضّفه ورشّه مية قبل الصبة الجاية، علشان الخرسانة الجديدة تتعشّق في القديمة."}]},{t:"quiz",q:{kind:"mcq",q:{en:"Where should a casting joint of a continuous beam be?",ar:"فاصل الصب في الكمرة المستمرة يبقى فين؟"},options:[{en:"about L/5 from a support",ar:"حوالي L/5 من الركيزة"},{en:"at the face of the support",ar:"عند وش الركيزة"},{en:"at mid-span",ar:"في نص البحر"}],answer:0,explain:{en:"At the support the shear and the moment peak; at mid-span the moment peaks; near L/5 both are small.",ar:"عند الركيزة القص والعزم في أقصاهم؛ وفي النص العزم في أقصاه؛ وجنب L/5 الاتنين صغيرين."}}}]},{id:"apply",title:{en:"Your building: does it need joints?",ar:"مبناك: محتاج فواصل؟"},blocks:[{t:"p",text:{en:"The RC block is 14 × 9 m — far below 40 m, and a regular rectangle: **no expansion or structural joint**. A 30 °C rise of the roof moves its ends by $10^{-5}\\times30\\times7 = 2.1$ mm; even with a rigid roof the upper columns (300 wide in that direction, $EI = 24750$ kN·m², $h = 3.2$ m) would take at most $6\\times24750\\times0.0021/3.2^2 = 30.5$ kN·m. Four such blocks in a row, 56 m, would need **one joint**: the end movement would drop from 8.4 to 4.2 mm and that upper bound from 121.8 to 60.9 kN·m.",ar:"المبنى الخرساني 14 × 9 م — أقل بكتير من 40 م، ومستطيل منتظم: **مش محتاج فاصل تمدد ولا فاصل إنشائي**. زيادة 30 درجة في حرارة السقف بتحرّك أطرافه $10^{-5}\\times30\\times7 = 2.1$ مم؛ وحتى بسقف جاسئ أعمدة الدور الأخير (عرضها 300 في الاتجاه ده، $EI = 24750$ kN·m²، و $h = 3.2$ م) كانت هتاخد بالكتير $6\\times24750\\times0.0021/3.2^2 = 30.5$ kN·m. ولو أربع بلوكات زيّه ورا بعض، 56 م، كانوا هيحتاجوا **فاصل واحد**: حركة الطرف تنزل من 8.4 لـ 4.2 مم والحد الأعلى ده من 121.8 لـ 60.9 kN·m."}},{t:"p",text:{en:"The steel workshop stands 8 m away on its own footings — a heavy two-storey RC block and a light steel shed are already separated, footings included. A covered link between them must not tie them together: an 8 m RC bridge, simply supported on **short cantilevers** of both buildings, hinged at one end and sliding at the other, with 2 cm gaps. Each of its two 250 × 600 beams carries $w = 12.15\\times1.2 + 3.94 = 18.52$ kN/m → $Q = 74.07$ kN, with friction $P = 0.2Q = 14.81$ kN. Corbel: $a = 0.20$ m, $t = 0.40$ m, 0.25 m at the edge: $M = 74.07\\times0.20 + 14.81\\times0.05 = 15.55$ kN·m → $A_s = 202$ mm² → 2Ø12. The bridge itself moves $10^{-5}\\times30\\times8 = 2.4$ mm — the gaps take it easily. Click a footing.",ar:"الورشة المعدنية واقفة على بعد 8 م على قواعدها — مبنى خرساني دورين تقيل وهنجر معدني خفيف منفصلين أصلاً، بالقواعد. والممر المسقوف بينهم لازم مايربطهمش ببعض: كوبري خرساني 8 م، بسيط الارتكاز على **كوابيل قصيرة** من المبنيين، مفصلي من طرف ومنزلق من التاني، بفواصل 2 سم. كل كمرة من كمرتيه 250 × 600 شايلة $w = 12.15\\times1.2 + 3.94 = 18.52$ kN/m ← $Q = 74.07$ kN، واحتكاك $P = 0.2Q = 14.81$ kN. الكابولي القصير: $a = 0.20$ م، و $t = 0.40$ م، و 0.25 م عند الطرف: $M = 74.07\\times0.20 + 14.81\\times0.05 = 15.55$ kN·m ← $A_s = 202$ مم² ← 2Ø12. والكوبري نفسه بيتحرك $10^{-5}\\times30\\times8 = 2.4$ مم — والفواصل بتاخدها بسهولة. اضغط على قاعدة."}},{t:"widget",w:"building",props:{focus:"F-B4",tags:["footings","cols-g","beams-1","slab-1","cols-1","beams-2","slab-2","ws-columns","ws-trusses","sys-joints"]}},{t:"quiz",q:{kind:"num",q:{en:"A 56 m version of the block without joints, ΔT = 30 °C: free movement of each end (mm)?",ar:"نسخة 56 م من المبنى من غير فواصل، و ΔT = 30 درجة: الحركة الحرة لكل طرف (مم)؟"},answer:8.4,tol:.003,unit:"mm",explain:{en:"$10^{-5}\\times30\\times28 = 8.4$ mm.",ar:"$10^{-5}\\times30\\times28 = 8.4$ مم."}}}]}],quiz:[{kind:"mcq",q:{en:"A heavy 8-storey block stands next to a single-storey hall on soft clay. The joint between them is…",ar:"بلوك تقيل 8 أدوار جنب صالة دور واحد على طين ضعيف. الفاصل بينهم…"},options:[{en:"a settlement joint, through the footings",ar:"فاصل هبوط، عابر للقواعد"},{en:"an expansion joint on twin columns",ar:"فاصل تمدد على عمودين توأم"},{en:"a casting joint",ar:"فاصل صب"}],answer:0,explain:{en:"Heavy next to light on soft soil settles unequally; the parts need separate footings.",ar:"التقيل جنب الخفيف على تربة ضعيفة بيهبطوا بشكل مختلف؛ والأجزاء محتاجة قواعد منفصلة."}},{kind:"num",q:{en:"A part 36 m long warms by 30 °C. Free movement of each end (mm)?",ar:"جزء طوله 36 م سخن 30 درجة. الحركة الحرة لكل طرف (مم)؟"},answer:5.4,tol:.003,unit:"mm",explain:{en:"$10^{-5}\\times30\\times18 = 5.4$ mm.",ar:"$10^{-5}\\times30\\times18 = 5.4$ مم."}},{kind:"tf",q:{en:"An expansion joint does not have to cut through the footings.",ar:"فاصل التمدد مش لازم يقطع القواعد."},answer:!0,explain:{en:"The footings are buried and hardly change temperature; twin columns may share one footing.",ar:"القواعد مدفونة وحرارتها تقريباً مابتتغيّرش؛ والعمودين التوأم ممكن يشتركوا في قاعدة واحدة."}},{kind:"num",q:{en:"Corbel: Q = 180 kN at a = 0.2 m, P = 36 kN, t − d = 0.05 m. Moment at the face (kN·m)?",ar:"كابولي قصير: Q = 180 kN على a = 0.2 م، و P = 36 kN، و t − d = 0.05 م. العزم عند الوش (kN·m)؟"},answer:37.8,tol:.003,unit:"kN·m",explain:{en:"$180\\times0.2 + 36\\times0.05 = 36 + 1.8 = 37.8$ kN·m.",ar:"$180\\times0.2 + 36\\times0.05 = 36 + 1.8 = 37.8$ kN·m."}},{kind:"num",q:{en:"A corbel projects 0.35 m to its load. Smallest depth at the column face (m)?",ar:"كابولي قصير حمله على بعد 0.35 م من وش العمود. أقل عمق عند وش العمود (م)؟"},answer:.35,tol:.003,unit:"m",explain:{en:"t ≥ a = 0.35 m.",ar:"t ≥ a = 0.35 م."}},{kind:"mcq",q:{en:"Roof upstands at an expansion joint are about…",ar:"الدروتين عند فاصل التمدد في السطح حوالي…"},options:[{en:"22 cm high and 10 cm wide",ar:"22 سم ارتفاع و 10 سم عرض"},{en:"5 cm high and 2 cm wide",ar:"5 سم ارتفاع و 2 سم عرض"},{en:"1 m high",ar:"1 م ارتفاع"}],answer:0,explain:{en:"High enough to keep the water and the insulation above the slot.",ar:"عالية كفاية تخلّي المية والعزل فوق الشق."}},{kind:"tf",q:{en:"A bridge between two buildings may be cast continuous with both of them.",ar:"الكوبري بين مبنيين ممكن يتصب مستمر معاهم الاتنين."},answer:!1,explain:{en:"It would tie them together; it must be determinate — simply supported on short cantilevers, hinged at one end and sliding at the other.",ar:"كده هيربطهم ببعض؛ لازم يبقى محدد — بسيط الارتكاز على كوابيل قصيرة، مفصلي من طرف ومنزلق من التاني."}},{kind:"num",q:{en:"Two equal spans of 10 m, EI = 300000 kN·m²; the middle support settles 20 mm. Change of the support moment (kN·m)?",ar:"بحرين متساويين 10 م، و EI = 300000 kN·m²؛ والركيزة الوسطية هبطت 20 مم. التغيير في عزم الركيزة (kN·m)؟"},answer:180,tol:.003,unit:"kN·m",explain:{en:"$3EI\\Delta/L^2 = 3\\times300000\\times0.02/100 = 180$ kN·m.",ar:"$3EI\\Delta/L^2 = 3\\times300000\\times0.02/100 = 180$ kN·m."}}]};export{r as default};
